:root {
  --bg: #f4f5f7;
  --panel: #ffffff;
  --ink: #1f2430;
  --muted: #6b7280;
  --line: #e5e7eb;
  --brand: #4f46e5;
  --brand-dark: #4338ca;
  --danger: #dc2626;
  --green: #059669;
  --amber: #d97706;
  --shadow: 0 1px 3px rgba(17, 24, 39, 0.08), 0 1px 2px rgba(17, 24, 39, 0.04);
  --radius: 10px;
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--ink);
  font-size: 14px;
}

.app { display: grid; grid-template-columns: 260px 1fr; height: 100vh; }

/* ---------------------------------------------------------------- sidebar */
.sidebar {
  background: var(--panel);
  border-right: 1px solid var(--line);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  overflow-y: auto;
}
.brand { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 18px; }
.brand-mark { font-size: 20px; }

.scopes { display: flex; flex-direction: column; gap: 2px; }
.scope {
  text-align: left; border: none; background: none; padding: 8px 10px;
  border-radius: 8px; cursor: pointer; color: var(--ink); font-size: 14px;
}
.scope:hover { background: #f3f4f6; }
.scope.active { background: #eef2ff; color: var(--brand-dark); font-weight: 600; }

.side-section { border-top: 1px solid var(--line); padding-top: 14px; }
.side-head {
  display: flex; justify-content: space-between; align-items: baseline;
  font-size: 12px; text-transform: uppercase; letter-spacing: .04em;
  color: var(--muted); font-weight: 600; margin-bottom: 8px;
}
.hint { text-transform: none; letter-spacing: 0; font-weight: 400; font-size: 11px; }

.views-list, .tags-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; }
.views-list li, .tags-list li {
  display: flex; align-items: center; justify-content: space-between;
  padding: 6px 10px; border-radius: 8px; cursor: pointer; gap: 6px;
}
.views-list li:hover, .tags-list li:hover { background: #f3f4f6; }
.views-list li.active { background: #eef2ff; color: var(--brand-dark); font-weight: 600; }
.tag-count { color: var(--muted); font-size: 12px; }
.tags-list li.include { background: #ecfdf5; color: var(--green); font-weight: 600; }
.tags-list li.exclude { background: #fef2f2; color: var(--danger); font-weight: 600; text-decoration: line-through; }
.tag-state { font-size: 12px; width: 14px; text-align: center; }
.view-del { opacity: 0; color: var(--muted); }
.views-list li:hover .view-del { opacity: 1; }

.side-io { display: flex; gap: 14px; margin-top: auto; }

/* ------------------------------------------------------------------- main */
.main { display: flex; flex-direction: column; overflow: hidden; }
.topbar {
  display: flex; gap: 12px; padding: 14px 20px; border-bottom: 1px solid var(--line);
  background: var(--panel);
}
.search-wrap { flex: 1; }
#search {
  width: 100%; padding: 10px 14px; border: 1px solid var(--line);
  border-radius: 8px; font-size: 14px; background: #fff;
}
#search:focus { outline: none; border-color: var(--brand); box-shadow: 0 0 0 3px rgba(79,70,229,.12); }

.active-filters { padding: 10px 20px 0; display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.filter-chip {
  display: inline-flex; align-items: center; gap: 6px; padding: 3px 10px;
  border-radius: 999px; font-size: 12px; background: #eef2ff; color: var(--brand-dark);
}
.filter-chip.exclude { background: #fef2f2; color: var(--danger); }
.filter-chip button { border: none; background: none; cursor: pointer; color: inherit; font-size: 13px; padding: 0; }

.bulk-bar {
  display: flex; align-items: center; justify-content: space-between;
