:root {
  --bg: #f4f5f7;
  --panel: #ffffff;
  --ink: #1f2430;
  --muted: #6b7280;
  --line: #e5e7eb;
  --brand: #4f46e5;
  --brand-dark: #4338ca;
  --danger: #dc2626;
  --green: #059669;
  --amber: #d97706;
  --shadow: 0 1px 3px rgba(17, 24, 39, 0.08), 0 1px 2px rgba(17, 24, 39, 0.04);
  --radius: 10px;
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--ink);
  font-size: 14px;
}

.app { display: grid; grid-template-columns: 260px 1fr; height: 100vh; }

/* ---------------------------------------------------------------- sidebar */
.sidebar {
  background: var(--panel);
  border-right: 1px solid var(--line);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  overflow-y: auto;
}
.brand { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 18px; }
.brand-mark { font-size: 20px; }

.scopes { display: flex; flex-direction: column; gap: 2px; }
.scope {
  text-align: left; border: none; background: none; padding: 8px 10px;
  border-radius: 8px; cursor: pointer; color: var(--ink); font-size: 14px;
}
.scope:hover { background: #f3f4f6; }
.scope.active { background: #eef2ff; color: var(--brand-dark); font-weight: 600; }

.side-section { border-top: 1px solid var(--line); padding-top: 14px; }
.side-head {
  display: flex; justify-content: space-between; align-items: baseline;
  font-size: 12px; text-transform: uppercase; letter-spacing: .04em;
  color: var(--muted); font-weight: 600; margin-bottom: 8px;
}
.hint { text-transform: none; letter-spacing: 0; font-weight: 400; font-size: 11px; }

.views-list, .tags-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; }
.views-list li, .tags-list li {
  display: flex; align-items: center; justify-content: space-between;
  padding: 6px 10px; border-radius: 8px; cursor: pointer; gap: 6px;
}
.views-list li:hover, .tags-list li:hover { background: #f3f4f6; }
.views-list li.active { background: #eef2ff; color: var(--brand-dark); font-weight: 600; }
.tag-count { color: var(--muted); font-size: 12px; }
.tags-list li.include { background: #ecfdf5; color: var(--green); font-weight: 600; }
.tags-list li.exclude { background: #fef2f2; color: var(--danger); font-weight: 600; text-decoration: line-through; }
.tag-state { font-size: 12px; width: 14px; text-align: center; }
.view-del { opacity: 0; color: var(--muted); }
.views-list li:hover .view-del { opacity: 1; }

.side-io { display: flex; gap: 14px; margin-top: auto; }

/* ------------------------------------------------------------------- main */
.main { display: flex; flex-direction: column; overflow: hidden; }
.topbar {
  display: flex; gap: 12px; padding: 14px 20px; border-bottom: 1px solid var(--line);
  background: var(--panel);
}
.search-wrap { flex: 1; }
#search {
  width: 100%; padding: 10px 14px; border: 1px solid var(--line);
  border-radius: 8px; font-size: 14px; background: #fff;
}
#search:focus { outline: none; border-color: var(--brand); box-shadow: 0 0 0 3px rgba(79,70,229,.12); }

.active-filters { padding: 10px 20px 0; display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.filter-chip {
  display: inline-flex; align-items: center; gap: 6px; padding: 3px 10px;
  border-radius: 999px; font-size: 12px; background: #eef2ff; color: var(--brand-dark);
}
.filter-chip.exclude { background: #fef2f2; color: var(--danger); }
.filter-chip button { border: none; background: none; cursor: pointer; color: inherit; font-size: 13px; padding: 0; }

.bulk-bar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 20px; background: #eef2ff; border-bottom: 1px solid var(--line); gap: 12px;
}
.bulk-actions { display: flex; gap: 6px; flex-wrap: wrap; }
.check { display: flex; align-items: center; gap: 8px; font-weight: 600; }

.list { padding: 16px 20px; overflow-y: auto; display: flex; flex-direction: column; gap: 10px; }

/* ------------------------------------------------------------------- card */
.card {
  display: grid; grid-template-columns: auto auto 1fr auto; gap: 12px; align-items: start;
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 12px 14px; box-shadow: var(--shadow);
}
.card.selected { border-color: var(--brand); box-shadow: 0 0 0 2px rgba(79,70,229,.25); }
.card.archived { opacity: .7; }
.card-check { margin-top: 2px; }
.card-thumb {
  width: 88px; height: 60px; border-radius: 6px; object-fit: cover; background: #f3f4f6;
  border: 1px solid var(--line);
}
.card-thumb.placeholder { display: flex; align-items: center; justify-content: center; color: #cbd5e1; font-size: 22px; }
.card-body { min-width: 0; }
.card-title { display: flex; align-items: center; gap: 7px; }
.card-favicon { width: 16px; height: 16px; border-radius: 3px; flex: none; }
.card-title a {
  font-weight: 600; font-size: 15px; color: var(--ink); text-decoration: none;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.card-title a:hover { color: var(--brand); text-decoration: underline; }
.card-url { color: var(--muted); font-size: 12px; margin: 2px 0 4px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.card-desc { color: #374151; font-size: 13px; line-height: 1.45; margin: 0 0 6px;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.card-tags { display: flex; flex-wrap: wrap; gap: 5px; }
.chip {
  background: #f1f5f9; color: #475569; border-radius: 999px; padding: 2px 9px; font-size: 12px;
  cursor: pointer;
}
.chip:hover { background: #e2e8f0; }
.card-meta { color: var(--muted); font-size: 11px; margin-top: 6px; display: flex; gap: 10px; flex-wrap: wrap; }
.card-actions { display: flex; flex-direction: column; gap: 4px; align-items: flex-end; }
.card-actions .row { display: flex; gap: 2px; }
.icon-btn {
  border: none; background: none; cursor: pointer; padding: 5px; border-radius: 6px;
  font-size: 15px; line-height: 1; color: var(--muted);
}
.icon-btn:hover { background: #f3f4f6; }
.icon-btn.on-fav { color: var(--amber); }
.icon-btn.on-read { color: var(--brand); }
.badge {
  font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .03em;
  padding: 2px 6px; border-radius: 5px;
}
.badge.read { background: #eef2ff; color: var(--brand-dark); }
.badge.snap { background: #ecfdf5; color: var(--green); }

.empty { padding: 60px 20px; text-align: center; color: var(--muted); }
.empty h3 { color: var(--ink); }

/* ---------------------------------------------------------------- buttons */
.btn {
  border: 1px solid var(--line); background: #fff; color: var(--ink);
  padding: 8px 14px; border-radius: 8px; cursor: pointer; font-size: 14px; font-weight: 500;
}
.btn:hover { background: #f9fafb; }
.btn-primary { background: var(--brand); border-color: var(--brand); color: #fff; }
.btn-primary:hover { background: var(--brand-dark); }
.btn-danger { color: var(--danger); border-color: #fecaca; }
.btn-danger:hover { background: #fef2f2; }
.btn-ghost { border-color: transparent; background: transparent; color: var(--muted); }
.btn-ghost:hover { background: #f3f4f6; }
.btn-block { width: 100%; }
.btn-sm { padding: 5px 10px; font-size: 13px; }
.link-btn { border: none; background: none; color: var(--brand); cursor: pointer; font-size: 13px; padding: 0; }
.link-btn:hover { text-decoration: underline; }
.select { padding: 8px 10px; border: 1px solid var(--line); border-radius: 8px; background: #fff; font-size: 14px; }

/* ----------------------------------------------------------------- modal */
.modal-backdrop {
  position: fixed; inset: 0; background: rgba(17,24,39,.45);
  display: flex; align-items: flex-start; justify-content: center; padding: 40px 16px; z-index: 100;
  overflow-y: auto;
}
.modal {
  background: #fff; border-radius: 14px; width: 100%; max-width: 560px; box-shadow: 0 20px 50px rgba(0,0,0,.25);
}
.modal-head { display: flex; align-items: center; justify-content: space-between; padding: 18px 20px; border-bottom: 1px solid var(--line); }
.modal-head h2 { margin: 0; font-size: 18px; }
.form { padding: 18px 20px; display: flex; flex-direction: column; gap: 12px; }
.form label { display: flex; flex-direction: column; gap: 5px; font-size: 13px; font-weight: 600; color: #374151; }
.form input[type=text], .form textarea {
  padding: 9px 11px; border: 1px solid var(--line); border-radius: 8px; font-size: 14px; font-weight: 400; font-family: inherit;
}
.form input:focus, .form textarea:focus { outline: none; border-color: var(--brand); box-shadow: 0 0 0 3px rgba(79,70,229,.12); }
.form-row { display: flex; gap: 16px; flex-wrap: wrap; }
.form-media { gap: 12px; }
.grow { flex: 1; min-width: 200px; }
.inline { flex-direction: row !important; align-items: center; gap: 6px; font-weight: 500; }
.f-preview img { max-width: 100%; max-height: 160px; border-radius: 8px; border: 1px solid var(--line); }
.snapshot-row { font-size: 13px; color: var(--muted); }
.modal-foot { display: flex; justify-content: space-between; align-items: center; margin-top: 6px; }
.foot-left, .foot-right { display: flex; gap: 8px; }
.f-status { font-size: 13px; color: var(--muted); min-height: 16px; }
.note { margin: 0 20px; padding: 10px 12px; background: #fffbeb; border: 1px solid #fde68a; color: #92400e; border-radius: 8px; font-size: 13px; }

.toast {
  position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);
  background: #111827; color: #fff; padding: 10px 18px; border-radius: 8px; z-index: 200;
  box-shadow: 0 8px 24px rgba(0,0,0,.3); font-size: 14px;
}

@media (max-width: 720px) {
  .app { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .card { grid-template-columns: auto 1fr; }
  .card-thumb { display: none; }
}

