input.command:
cat > /tmp/nstest.mjs <<'EOF'
import { DatabaseSync } from 'node:sqlite';
const db = new DatabaseSync(':memory:');
try {
  db.exec('CREATE VIRTUAL TABLE f USING fts5(a)');
  db.exec("INSERT INTO f VALUES('hello world')");
  const rows = db.prepare("SELECT * FROM f WHERE f MATCH 'hello'").all();
  console.log('node:sqlite FTS5 OK', JSON.stringify(rows));
  // exercise run() return shape and named params
  db.exec('CREATE TABLE t(id INTEGER PRIMARY KEY, name TEXT)');
  const r = db.prepare('INSERT INTO t(name) VALUES(?)').run('x');
  console.log('run() ->', JSON.stringify({changes:r.changes, id: Number(r.lastInsertRowid)}));
} catch (e) {
  console.log('ERROR:', e.message);
}
db.close();
console.log('closed cleanly, exiting');
EOF
node --experimental-sqlite /tmp/nstest.mjs 2>&1 | grep -vE "ExperimentalWarning|trace-warning"; echo "[exit ${PIPESTATUS[0]}]"

